import{_ as o,r as e,o as c,c as l,e as i,a as s,b as a,d as p}from"./app-6c9584fa.js";const u={},r={href:"https://zod.dev/",target:"_blank",rel:"noopener noreferrer"},k={href:"https://docs.anthropic.com/en/docs/tool-use-examples",target:"_blank",rel:"noopener noreferrer"};function d(m,n){const t=e("ExternalLinkIcon");return c(),l("div",null,[n[8]||(n[8]=i(`<h1 id="第三章-我是如何剖析-claude-code-工具系统与命令执行机制的" tabindex="-1"><a class="header-anchor" href="#第三章-我是如何剖析-claude-code-工具系统与命令执行机制的" aria-hidden="true">#</a> 第三章：我是如何剖析 Claude Code 工具系统与命令执行机制的</h1><p>大家好。今天，我们将继续探索 Claude Code 的核心源码。</p><p>在上一章，我们弄懂了 QueryEngine 是如何管理对话循环的。但你有没有想过，远在云端的 Claude 3.5 模型，究竟是怎么在你的电脑上敲下 <code>npm install</code>、是怎么搜索代码、又是怎么修改文件的？</p><p>如果没有“手脚”，再聪明的大脑也只是一台陪聊机。今天，我们就来揭开让 Claude Code 真正动起来的核心秘密——<strong>工具系统（Tool System）</strong>。</p><p>学习完这章后，你会对以下内容有清晰的认识：</p><ol><li><strong>工具驱动架构</strong>：为什么在 Claude Code 里“万物皆工具”？</li><li><strong>依赖注入与生命周期</strong>：工具是怎么安全地跑起来的？</li><li><strong>深入 BashTool 源码</strong>：它怎么处理长输出？怎么防止死循环？</li><li><strong>动手实践</strong>：像官方一样，写一个真正的本地工具。</li></ol><hr><h2 id="一、宏观视角-万物皆工具的架构之美" tabindex="-1"><a class="header-anchor" href="#一、宏观视角-万物皆工具的架构之美" aria-hidden="true">#</a> 一、宏观视角：万物皆工具的架构之美</h2><p>如果说大模型是“大脑”，那么 <code>src/Tool.ts</code> 就是让大脑长出三头六臂的“基因图谱”。</p><p>打开 <code>src/Tool.ts</code>，你会看到一个极其庞大且严谨的 <code>Tool</code> 泛型接口。所有的能力——无论是 <code>BashTool</code>、<code>GlobTool</code> 还是外部的 MCP 服务——全都是这个接口的实现。</p><p>为了让大家有个直观的感受，我把 <code>src/Tool.ts</code> 中 <code>Tool</code> 接口的核心定义摘录了出来：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// 摘自 src/Tool.ts</span>
<span class="token keyword">export</span> <span class="token keyword">type</span> <span class="token class-name">Tool<span class="token operator">&lt;</span>
  Input <span class="token keyword">extends</span> AnyObject <span class="token operator">=</span> AnyObject<span class="token punctuation">,</span>
  Output <span class="token operator">=</span> <span class="token builtin">unknown</span><span class="token punctuation">,</span>
  <span class="token constant">P</span> <span class="token keyword">extends</span> ToolProgressData <span class="token operator">=</span> ToolProgressData<span class="token punctuation">,</span>
<span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token punctuation">{</span>
  <span class="token comment">// 1. 核心的执行逻辑：注入了大礼包 context</span>
  <span class="token function">call</span><span class="token punctuation">(</span>
    args<span class="token operator">:</span> z<span class="token punctuation">.</span>infer<span class="token operator">&lt;</span>Input<span class="token operator">&gt;</span><span class="token punctuation">,</span>
    context<span class="token operator">:</span> ToolUseContext<span class="token punctuation">,</span>
    canUseTool<span class="token operator">:</span> CanUseToolFn<span class="token punctuation">,</span>
    parentMessage<span class="token operator">:</span> AssistantMessage<span class="token punctuation">,</span>
    onProgress<span class="token operator">?</span><span class="token operator">:</span> ToolCallProgress<span class="token operator">&lt;</span><span class="token constant">P</span><span class="token operator">&gt;</span><span class="token punctuation">,</span>
  <span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">Promise</span><span class="token operator">&lt;</span>ToolResult<span class="token operator">&lt;</span>Output<span class="token operator">&gt;&gt;</span>

  <span class="token comment">// 2. 严格的输入校验（基于 Zod）</span>
  <span class="token keyword">readonly</span> inputSchema<span class="token operator">:</span> Input
  
  <span class="token comment">// 3. 统一的权限拦截</span>
  <span class="token function">checkPermissions</span><span class="token punctuation">(</span>
    input<span class="token operator">:</span> z<span class="token punctuation">.</span>infer<span class="token operator">&lt;</span>Input<span class="token operator">&gt;</span><span class="token punctuation">,</span>
    context<span class="token operator">:</span> ToolUseContext<span class="token punctuation">,</span>
  <span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">Promise</span><span class="token operator">&lt;</span>PermissionResult<span class="token operator">&gt;</span>

  <span class="token comment">// 4. 统一的 UI 渲染</span>
  <span class="token function">renderToolUseMessage</span><span class="token punctuation">(</span>
    input<span class="token operator">:</span> Partial<span class="token operator">&lt;</span>z<span class="token punctuation">.</span>infer<span class="token operator">&lt;</span>Input<span class="token operator">&gt;&gt;</span><span class="token punctuation">,</span>
    options<span class="token operator">:</span> <span class="token punctuation">{</span> theme<span class="token operator">:</span> ThemeName<span class="token punctuation">;</span> verbose<span class="token operator">:</span> <span class="token builtin">boolean</span><span class="token punctuation">;</span> commands<span class="token operator">?</span><span class="token operator">:</span> Command<span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token punctuation">)</span><span class="token operator">:</span> React<span class="token punctuation">.</span>ReactNode
  
  <span class="token comment">// ... 其他诸如 isConcurrencySafe, interruptBehavior 等细节</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>为什么要这么设计？我在源码中看出了三个字：<strong>大一统</strong>。</p><ul><li><strong>统一的入参校验</strong>：如源码中的 <code>readonly inputSchema: Input</code>。在大模型把 JSON 传过来时，系统第一步就是严格的类型校验，坚决不让非法的参数污染本地环境。</li><li><strong>统一的权限拦截</strong>：每个工具都要实现 <code>checkPermissions</code>。系统不用管你具体是什么工具，只要在这个层面上统一拦截，就能实现 <code>auto</code>、<code>plan</code>、<code>ask</code> 等多种权限模式。</li><li><strong>统一的 UI 渲染</strong>：<code>renderToolUseMessage</code> 要求返回 <code>React.ReactNode</code>，这直接把枯燥的执行日志变成了终端里漂亮的 React Ink 组件。</li></ul><hr><h2 id="二、精妙绝伦-依赖注入与上下文大礼包" tabindex="-1"><a class="header-anchor" href="#二、精妙绝伦-依赖注入与上下文大礼包" aria-hidden="true">#</a> 二、精妙绝伦：依赖注入与上下文大礼包</h2><p>在传统的代码里，如果一个工具想读取系统状态，可能会写满各种 <code>import store from &#39;...&#39;</code> 的全局单例。但这在复杂的 Agent 系统中是一场灾难。</p><p>Claude Code 的做法非常优雅：<strong>依赖注入（Dependency Injection）</strong>。</p><p>每次调用工具的 <code>call()</code> 方法时，系统都会给它塞一个超级大礼包——<code>ToolUseContext</code>。我在源码里给大家提炼出了它的核心骨架：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// 摘自 src/Tool.ts</span>
<span class="token keyword">export</span> <span class="token keyword">type</span> <span class="token class-name">ToolUseContext</span> <span class="token operator">=</span> <span class="token punctuation">{</span>
  options<span class="token operator">:</span> <span class="token punctuation">{</span>
    tools<span class="token operator">:</span> Tools                       <span class="token comment">// 让工具可以调用其他工具</span>
    commands<span class="token operator">:</span> Command<span class="token punctuation">[</span><span class="token punctuation">]</span>                <span class="token comment">// 可用命令</span>
    mcpClients<span class="token operator">:</span> MCPServerConnection<span class="token punctuation">[</span><span class="token punctuation">]</span>  <span class="token comment">// MCP 连接</span>
    <span class="token comment">// ...</span>
  <span class="token punctuation">}</span>
  abortController<span class="token operator">:</span> AbortController     <span class="token comment">// 极其重要！用来响应用户的 Ctrl+C 打断</span>
  <span class="token function">getAppState</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">:</span> AppState              <span class="token comment">// 读取当前大环境状态</span>
  <span class="token function">setAppState</span><span class="token punctuation">(</span><span class="token function-variable function">f</span><span class="token operator">:</span> <span class="token punctuation">(</span>prev<span class="token operator">:</span> AppState<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> AppState<span class="token punctuation">)</span><span class="token operator">:</span> <span class="token keyword">void</span> <span class="token comment">// 修改大环境状态</span>
  readFileState<span class="token operator">:</span> FileStateCache        <span class="token comment">// 文件状态缓存</span>
  messages<span class="token operator">:</span> Message<span class="token punctuation">[</span><span class="token punctuation">]</span>                  <span class="token comment">// 当前的聊天历史记录</span>
  <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这意味着什么？意味着一个工具在执行时，完全不需要关心外面的世界是怎么运转的。只要拿到这个 Context，它就能呼风唤雨。它甚至可以通过 <code>setAppState</code> 偷偷在后台起一个新的子任务进度条！</p><hr><h2 id="三、庖丁解牛-bashtool-里的魔鬼细节" tabindex="-1"><a class="header-anchor" href="#三、庖丁解牛-bashtool-里的魔鬼细节" aria-hidden="true">#</a> 三、庖丁解牛：BashTool 里的魔鬼细节</h2><p>为了让大家更有体感，我们来解剖一下系统里最危险、也最强大的工具：<code>src/tools/BashTool/BashTool.tsx</code>。</p><p>让大模型自由执行 Bash 命令，无异于让一个三岁小孩玩核按钮。官方是怎么防患于未然的呢？</p><h3 id="_1-聪明的-只读-搜索-命令折叠" tabindex="-1"><a class="header-anchor" href="#_1-聪明的-只读-搜索-命令折叠" aria-hidden="true">#</a> 1. 聪明的“只读/搜索”命令折叠</h3><p>当你让模型去排查一个 Bug 时，它可能会疯狂地 <code>grep</code>、<code>cat</code>、<code>ls</code>。如果这些命令的输出全都堆在终端里，你的屏幕早就被刷爆了。</p><p>在 <code>BashTool.tsx</code> 的开头，我发现了一个叫做 <code>isSearchOrReadBashCommand</code> 的神奇函数：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// 摘自 src/tools/BashTool/BashTool.tsx</span>
<span class="token keyword">const</span> <span class="token constant">BASH_SEARCH_COMMANDS</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Set</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string">&#39;find&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;grep&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;rg&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;ag&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;ack&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;locate&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;which&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;whereis&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> <span class="token constant">BASH_READ_COMMANDS</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Set</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string">&#39;cat&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;head&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;tail&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;less&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;more&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;wc&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;stat&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;file&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;jq&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;awk&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> <span class="token constant">BASH_LIST_COMMANDS</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Set</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string">&#39;ls&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;tree&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;du&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 在 BashTool 对象里，它会使用这些白名单来做判断</span>
<span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">isSearchOrReadBashCommand</span><span class="token punctuation">(</span>command<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token comment">// ... (省略复杂的管道、重定向解析逻辑)</span>
  <span class="token keyword">const</span> isPartSearch <span class="token operator">=</span> <span class="token constant">BASH_SEARCH_COMMANDS</span><span class="token punctuation">.</span><span class="token function">has</span><span class="token punctuation">(</span>baseCommand<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> isPartRead <span class="token operator">=</span> <span class="token constant">BASH_READ_COMMANDS</span><span class="token punctuation">.</span><span class="token function">has</span><span class="token punctuation">(</span>baseCommand<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token comment">// ...</span>
  <span class="token keyword">return</span> <span class="token punctuation">{</span> isSearch<span class="token operator">:</span> hasSearch<span class="token punctuation">,</span> isRead<span class="token operator">:</span> hasRead<span class="token punctuation">,</span> isList<span class="token operator">:</span> hasList <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>原来，系统维护了一份详细的“无害查询命令”白名单。当发现你在跑 <code>cat file | grep error</code> 时，UI 渲染层会直接把这些中间过程“折叠”起来，让你只看到最终的结论，界面清爽无比！</p><h3 id="_2-拦截危险的-孤狼-睡眠-sleep" tabindex="-1"><a class="header-anchor" href="#_2-拦截危险的-孤狼-睡眠-sleep" aria-hidden="true">#</a> 2. 拦截危险的“孤狼”睡眠（Sleep）</h3><p>有时候大模型会犯傻，想等某个文件生成，于是直接敲了个 <code>sleep 10</code>。这会让整个主线程傻等 10 秒！</p><p>源码中专门写了一个 <code>detectBlockedSleepPattern</code> 拦截器：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// 摘自 src/tools/BashTool/BashTool.tsx</span>
<span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">detectBlockedSleepPattern</span><span class="token punctuation">(</span>command<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">string</span> <span class="token operator">|</span> <span class="token keyword">null</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> parts <span class="token operator">=</span> <span class="token function">splitCommand_DEPRECATED</span><span class="token punctuation">(</span>command<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>parts<span class="token punctuation">.</span>length <span class="token operator">===</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token keyword">null</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> first <span class="token operator">=</span> parts<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token operator">?.</span><span class="token function">trim</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">??</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">;</span>
  
  <span class="token comment">// 识别整数秒数的 sleep</span>
  <span class="token keyword">const</span> m <span class="token operator">=</span> <span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">^sleep\\s+(\\d+)\\s*$</span><span class="token regex-delimiter">/</span></span><span class="token punctuation">.</span><span class="token function">exec</span><span class="token punctuation">(</span>first<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>m<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token keyword">null</span><span class="token punctuation">;</span>
  
  <span class="token keyword">const</span> secs <span class="token operator">=</span> <span class="token function">parseInt</span><span class="token punctuation">(</span>m<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token operator">!</span><span class="token punctuation">,</span> <span class="token number">10</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>secs <span class="token operator">&lt;</span> <span class="token number">2</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token keyword">null</span><span class="token punctuation">;</span> <span class="token comment">// 2秒以内的缓冲是允许的，比如防限流</span>

  <span class="token keyword">const</span> rest <span class="token operator">=</span> parts<span class="token punctuation">.</span><span class="token function">slice</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">join</span><span class="token punctuation">(</span><span class="token string">&#39; &#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">trim</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token comment">// 如果单独跑 sleep N，会被拦截并建议大模型改用专用的后台监控工具！</span>
  <span class="token keyword">return</span> rest <span class="token operator">?</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">sleep </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>secs<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string"> followed by: </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>rest<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span> <span class="token operator">:</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">standalone sleep </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>secs<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-长输出截断-防-token-爆炸" tabindex="-1"><a class="header-anchor" href="#_3-长输出截断-防-token-爆炸" aria-hidden="true">#</a> 3. 长输出截断（防 Token 爆炸）</h3><p>如果模型手滑，跑了一个 <code>cat package-lock.json</code>，几万行的输出不仅会挤爆终端，还会瞬间耗尽你的 API Token 预算（而且非常贵）。</p><p>Claude Code 采用了 <code>EndTruncatingAccumulator</code>。它不会把所有输出都塞进内存，而是像一个两头漏风的管子：保留开头的几百行，保留结尾的报错信息，中间的一大段全部替换为 <code>[... truncated ...]</code>。</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// 摘自 src/tools/BashTool/BashTool.tsx (工具执行阶段)</span>
<span class="token keyword">const</span> stdoutAccumulator <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">EndTruncatingAccumulator</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// ... 在命令执行完成或流式收集输出时 ...</span>
stdoutAccumulator<span class="token punctuation">.</span><span class="token function">append</span><span class="token punctuation">(</span><span class="token punctuation">(</span>result<span class="token punctuation">.</span>stdout <span class="token operator">||</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">trimEnd</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token constant">EOL</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">if</span> <span class="token punctuation">(</span>result<span class="token punctuation">.</span>code <span class="token operator">!==</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  stdoutAccumulator<span class="token punctuation">.</span><span class="token function">append</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">Exit code </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>result<span class="token punctuation">.</span>code<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token comment">// 最终将截断后（保留头尾，中间省略）的字符串交给大模型</span>
<span class="token keyword">const</span> stdout <span class="token operator">=</span> stdoutAccumulator<span class="token punctuation">.</span><span class="token function">toString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这种设计既保证了大模型能看到执行结果的头尾（通常报错都在尾部），又极大地省了钱！</p><hr><h2 id="四、动手实践-写一个极简的本地工具" tabindex="-1"><a class="header-anchor" href="#四、动手实践-写一个极简的本地工具" aria-hidden="true">#</a> 四、动手实践：写一个极简的本地工具</h2><p>看了这么多源码，手痒了吗？官方提供了一个非常好用的 <code>buildTool</code> 辅助函数。我们来模仿源码的风格，写一个只读的 <code>GitStatusTool</code>，帮大模型快速获取当前仓库的干净程度。</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">import</span> <span class="token punctuation">{</span> z <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;zod/v4&#39;</span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token punctuation">{</span> buildTool <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;../Tool.js&#39;</span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token punctuation">{</span> exec <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;child_process&#39;</span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token punctuation">{</span> promisify <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;util&#39;</span><span class="token punctuation">;</span>

<span class="token keyword">const</span> execAsync <span class="token operator">=</span> <span class="token function">promisify</span><span class="token punctuation">(</span>exec<span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 🟢 我们的实战代码：极简版 Git 状态工具</span>
<span class="token keyword">export</span> <span class="token keyword">const</span> GitStatusTool <span class="token operator">=</span> <span class="token function">buildTool</span><span class="token punctuation">(</span><span class="token punctuation">{</span>
  name<span class="token operator">:</span> <span class="token string">&#39;GitStatus&#39;</span><span class="token punctuation">,</span>
  description<span class="token operator">:</span> <span class="token string">&#39;获取当前代码库的 git 状态&#39;</span><span class="token punctuation">,</span>
  
  <span class="token comment">// 1. 严谨的输入校验</span>
  inputSchema<span class="token operator">:</span> z<span class="token punctuation">.</span><span class="token function">object</span><span class="token punctuation">(</span><span class="token punctuation">{</span>
    directory<span class="token operator">:</span> z<span class="token punctuation">.</span><span class="token function">string</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">optional</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">describe</span><span class="token punctuation">(</span><span class="token string">&#39;要检查的目录路径，默认当前路径&#39;</span><span class="token punctuation">)</span>
  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
  
  <span class="token comment">// 2. 告诉系统这是绝对安全的只读操作，不需要弹窗警告</span>
  <span class="token function-variable function">isReadOnly</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token boolean">true</span><span class="token punctuation">,</span> 
  
  <span class="token comment">// 3. 核心执行逻辑</span>
  <span class="token keyword">async</span> <span class="token function">call</span><span class="token punctuation">(</span><span class="token punctuation">{</span> directory <span class="token punctuation">}</span><span class="token punctuation">,</span> context<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> cwd <span class="token operator">=</span> directory <span class="token operator">||</span> process<span class="token punctuation">.</span><span class="token function">cwd</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">try</span> <span class="token punctuation">{</span>
      <span class="token comment">// 真实执行系统命令</span>
      <span class="token keyword">const</span> <span class="token punctuation">{</span> stdout <span class="token punctuation">}</span> <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">execAsync</span><span class="token punctuation">(</span><span class="token string">&#39;git status --short&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> cwd <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
      <span class="token keyword">return</span> <span class="token punctuation">{</span> 
        data<span class="token operator">:</span> stdout<span class="token punctuation">.</span><span class="token function">trim</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">||</span> <span class="token string">&#39;当前分支很干净，没有任何未提交的修改。&#39;</span> 
      <span class="token punctuation">}</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span>error<span class="token punctuation">)</span> <span class="token punctuation">{</span>
      <span class="token keyword">return</span> <span class="token punctuation">{</span> data<span class="token operator">:</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">执行失败: </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>error<span class="token punctuation">.</span>message<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>只要把这个 Tool 注册进上下文的 <code>tools</code> 数组里，大模型就能随时调用它了！这就是工具驱动架构的魅力——插拔式扩展，毫无违和感。</p><hr><h2 id="五、小结" tabindex="-1"><a class="header-anchor" href="#五、小结" aria-hidden="true">#</a> 五、小结</h2><p>今天先到这，我们已经深入体会了工具系统作为 Claude Code “改变现实世界”桥梁的精妙之处。</p><p>通过一套统一的 <code>Tool</code> 接口，它实现了严格的 Zod 校验、基于 Context 的依赖注入，以及优雅的 UI 渲染折叠。而在看似简单的 <code>BashTool</code> 背后，隐藏着命令分类折叠、死等拦截、长输出截断等无数打磨细节。</p><p>Claude Code 源码系列还未完结。敬请期待！一键三连，关注不迷路。</p><hr><h2 id="六、推荐阅读" tabindex="-1"><a class="header-anchor" href="#六、推荐阅读" aria-hidden="true">#</a> 六、推荐阅读</h2>`,51)),s("ul",null,[s("li",null,[s("a",r,[n[0]||(n[0]=a("Zod 官方文档",-1)),p(t)]),n[1]||(n[1]=a(" —— 学习如何在 TypeScript 中写出像魔法一样严谨的运行时类型校验。",-1))]),s("li",null,[s("a",k,[n[2]||(n[2]=a("Anthropic Tool Use 官方指南",-1)),p(t)]),n[3]||(n[3]=a(" —— 了解大模型是如何理解你写的 ",-1)),n[4]||(n[4]=s("code",null,"description",-1)),n[5]||(n[5]=a(" 和 ",-1)),n[6]||(n[6]=s("code",null,"inputSchema",-1)),n[7]||(n[7]=a(" 的。",-1))])])])}const b=o(u,[["render",d],["__file","03-tool-system.html.vue"]]);export{b as default};
